import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const STATES = new Set(['pending', 'succeeded', 'failed']);

const isPlainObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const isValidId = v => typeof v === 'string' && v.length > 0;

/** Binary min-heap over strings using JS `<` code-unit ordering. */
class MinHeap {
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  push(v) {
    const a = this.a;
    a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function validate(spec) {
  if (!Array.isArray(spec)) throw new Error('spec must be an array of jobs');
  const jobs = new Map();
  spec.forEach((job, index) => {
    if (!isPlainObject(job)) throw new Error(`job at index ${index} must be an object`);
    const { id, deps, state } = job;
    if (!isValidId(id)) throw new Error(`job at index ${index} has an invalid id`);
    if (jobs.has(id)) throw new Error(`duplicate job id: ${JSON.stringify(id)}`);
    if (!Array.isArray(deps)) throw new Error(`job ${JSON.stringify(id)}: deps must be an array`);
    const seen = new Set();
    for (const dep of deps) {
      if (!isValidId(dep)) throw new Error(`job ${JSON.stringify(id)}: invalid dependency id`);
      if (seen.has(dep)) throw new Error(`job ${JSON.stringify(id)}: duplicate dependency ${JSON.stringify(dep)}`);
      seen.add(dep);
    }
    if (typeof state !== 'string' || !STATES.has(state)) {
      throw new Error(`job ${JSON.stringify(id)}: state must be pending, succeeded, or failed`);
    }
    jobs.set(id, { id, deps: [...deps], state });
  });
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error(`job ${JSON.stringify(job.id)}: unknown dependency ${JSON.stringify(dep)}`);
    }
  }
  return jobs;
}

export function planJobs(spec) {
  const jobs = validate(spec);

  // Kahn's algorithm over the entire graph, always taking the lexically smallest ready id.
  const indegree = new Map();
  const children = new Map();
  for (const id of jobs.keys()) { indegree.set(id, 0); children.set(id, []); }
  for (const job of jobs.values()) {
    indegree.set(job.id, job.deps.length);
    for (const dep of job.deps) children.get(dep).push(job.id);
  }
  const heap = new MinHeap();
  for (const [id, d] of indegree) if (d === 0) heap.push(id);
  const topo = [];
  while (heap.size > 0) {
    const id = heap.pop();
    topo.push(id);
    for (const child of children.get(id)) {
      const d = indegree.get(child) - 1;
      indegree.set(child, d);
      if (d === 0) heap.push(child);
    }
  }
  if (topo.length !== jobs.size) throw new Error('dependency cycle detected');

  // Failed ancestors, propagated in topological order through every intermediate state.
  const failedAncestors = new Map();
  for (const id of topo) {
    const set = new Set();
    for (const dep of jobs.get(id).deps) {
      if (jobs.get(dep).state === 'failed') set.add(dep);
      for (const f of failedAncestors.get(dep)) set.add(f);
    }
    failedAncestors.set(id, set);
  }

  const order = [], ready = [], blocked = [];
  for (const id of topo) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    const causes = failedAncestors.get(id);
    if (causes.size > 0) {
      blocked.push({ id, causes: [...causes].sort() });
      continue;
    }
    order.push(id);
    if (job.deps.every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
  }
  ready.sort();
  blocked.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return { order, ready, blocked };
}

function main(argv) {
  const fail = message => {
    process.stderr.write(`${message}\n`);
    process.exitCode = 2;
  };
  if (argv.length !== 1) return fail('usage: node job-plan.js SPECFILE');
  let text;
  try { text = readFileSync(argv[0], 'utf8'); } catch (err) { return fail(`cannot read ${argv[0]}: ${err.message}`); }
  let spec;
  try { spec = JSON.parse(text); } catch (err) { return fail(`invalid JSON: ${err.message}`); }
  let plan;
  try { plan = planJobs(spec); } catch (err) { return fail(`invalid job graph: ${err.message}`); }
  process.stdout.write(`${JSON.stringify(plan)}\n`);
}

function isMainModule() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isMainModule()) main(process.argv.slice(2));
