import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { planJobs } from '../job-plan.js';
const job = (id, deps = [], state = 'pending') => ({ id, deps, state });
const BIN = new URL('../job-plan.js', import.meta.url).pathname;

test('Kahn picks smallest zero-indegree each step, not sorted waves', () => {
  // a -> c, b has no deps. After removing a, c is available and beats z? No: c > b, so b, then c, then z.
  const r = planJobs([job('z'), job('c', ['a']), job('a'), job('b')]);
  assert.deepEqual(r.order, ['a', 'b', 'c', 'z']);
  // But if 'aa' depends on 'a', 'aa' is chosen right after 'a' even though 'b' was waiting.
  const r2 = planJobs([job('b'), job('aa', ['a']), job('a')]);
  assert.deepEqual(r2.order, ['a', 'aa', 'b']);
});

test('code-unit ordering, unicode and whitespace ids preserved', () => {
  const r = planJobs([job('b'), job('B'), job(' a'), job('é'), job('Z')]);
  assert.deepEqual(r.order, [' a', 'B', 'Z', 'b', 'é']);
  assert.deepEqual(r.ready, [' a', 'B', 'Z', 'b', 'é']);
});

test('order of pending jobs is drawn from the full-graph ordering', () => {
  // succeeded 'm' sits between; pending 'n' depends on m; 'a' pending with no deps.
  const r = planJobs([job('n', ['m']), job('m', [], 'succeeded'), job('a')]);
  assert.deepEqual(r, { order: ['a', 'n'], ready: ['a', 'n'], blocked: [] });
});

test('blocked causes include all failed ancestors through succeeded/failed intermediates', () => {
  const r = planJobs([
    job('f1', [], 'failed'), job('f2', ['f1'], 'failed'), job('s', ['f2'], 'succeeded'),
    job('p', ['s', 'f3']), job('f3', [], 'failed'), job('q', ['p']),
  ]);
  assert.deepEqual(r, {
    order: [], ready: [],
    blocked: [{ id: 'p', causes: ['f1', 'f2', 'f3'] }, { id: 'q', causes: ['f1', 'f2', 'f3'] }],
  });
});

test('ready reflects input states, not simulated execution', () => {
  const r = planJobs([job('a'), job('b', ['a']), job('c', ['s']), job('s', [], 'succeeded')]);
  assert.deepEqual(r, { order: ['a', 'b', 'c', 's'].filter(x => x !== 's'), ready: ['a', 'c'], blocked: [] });
});

test('validation errors', () => {
  assert.throws(() => planJobs([job('a', ['a'])]), /cycle/);
  assert.throws(() => planJobs([job('a', ['b'], 'failed'), job('b', ['a'], 'succeeded')]), /cycle/);
  assert.throws(() => planJobs([job('a'), job('a')]), /duplicate/);
  assert.throws(() => planJobs([job('a', ['b', 'b']), job('b')]), /duplicate/);
  assert.throws(() => planJobs([job('')]));
  assert.throws(() => planJobs([job('a', [], 'Pending')]));
  assert.throws(() => planJobs([job('a', [], 'done')]));
  assert.throws(() => planJobs([job(1)]));
  assert.throws(() => planJobs([{ id: 'a', deps: 'x', state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [''], state: 'pending' }]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs({}));
  assert.throws(() => planJobs([{ id: 'a', state: 'pending' }]));
});

test('__proto__ and constructor are ordinary ids; input not mutated; extra fields ignored', () => {
  const spec = [job('constructor', ['__proto__']), job('__proto__'), { ...job('x'), extra: 1 }];
  const snapshot = JSON.stringify(spec);
  const r = planJobs(spec);
  assert.deepEqual(r, { order: ['__proto__', 'constructor', 'x'], ready: ['__proto__', 'x'], blocked: [] });
  assert.equal(JSON.stringify(spec), snapshot);
});

test('CLI behaviour', () => {
  const dir = mkdtempSync(join(tmpdir(), 'jobplan-'));
  const good = join(dir, 'good.json');
  writeFileSync(good, JSON.stringify([job('b', ['a']), job('a')]));
  let r = spawnSync(process.execPath, [BIN, good], { encoding: 'utf8' });
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, JSON.stringify({ order: ['a', 'b'], ready: ['a'], blocked: [] }) + '\n');

  const bad = join(dir, 'bad.json');
  writeFileSync(bad, '{not json');
  for (const args of [[], [good, good], [join(dir, 'missing.json')], [bad]]) {
    r = spawnSync(process.execPath, [BIN, ...args], { encoding: 'utf8' });
    assert.equal(r.status, 2, `args ${JSON.stringify(args)}`);
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  }
  const cyc = join(dir, 'cyc.json');
  writeFileSync(cyc, JSON.stringify([job('a', ['a'])]));
  r = spawnSync(process.execPath, [BIN, cyc], { encoding: 'utf8' });
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.ok(r.stderr.length > 0);
});
